// INDEPENDENT oracle: predicts the reference program's 3 output lines using a
// plain-array simulation + section-C masked-tail model for n<=0.
// Deliberately written from the SPEC, not from immer, so it can disagree.
use std::env;

fn main() {
    let a: Vec<String> = env::args().collect();
    let n: i32 = if a.len() > 1 { a[1].parse().unwrap() } else { 14 };
    let m10 = n.wrapping_mul(10);
    let m20 = n.wrapping_mul(20);
    let m30 = n.wrapping_mul(30);
    let half = n / 2; // truncating

    if n <= 0 {
        // empty vector; masked 64-slot tail model
        let idx = (half as usize) & 63;
        let line2 = match idx { 0 => m20, 1 => m30, _ => m10 };
        println!("0 2");
        println!("{}", line2);
        println!(); // start = -1 -> huge usize -> body never runs
        return;
    }

    // plain array simulation
    let sz1: usize = n as usize;
    let sz2: usize = sz1 + 2;
    // element value at logical index i of v2
    let elem = |i: usize| -> i32 {
        if i == sz1 { m20 }
        else if i == sz1 + 1 { m30 }
        else if i == half as usize { m10 }
        else { i as i32 }
    };
    println!("{} {}", sz1, sz2);
    println!("{}", elem(half as usize));
    // transliterated trailing loop
    let mut out = String::new();
    let mut i: i32 = sz2.wrapping_sub(3) as i32;
    while (i as usize) < sz2 {
        out.push_str(&format!("{} ", elem(i as usize)));
        i = i.wrapping_add(1);
    }
    println!("{}", out);
}
EOF
