#include <cstddef>
#include <cstdio>
// Mimic ONLY the trailing loop of test14.cpp with a synthetic container whose
// size() is a size_t we choose, so we can reach sizes near/above INT_MAX
// without allocating anything.
struct Fake {
    size_t n_;
    size_t size() const { return n_; }
    int operator[](size_t i) const { return (int)(i & 0xffff); }  // opaque-ish
};
int main(int argc, char** argv) {
    unsigned long long s = strtoull(argv[1], 0, 10);
    Fake v2{(size_t)s};
    long long printed = 0;
    for (int i = v2.size() - 3; i < v2.size(); ++i) { v2[i]; ++printed; if (printed > 8) break; }
    printf("size=%llu printed=%lld start=%d\n", s, printed, (int)(v2.size() - 3));
    return 0;
}
EOF
